-- Mentor Profile: real, structured content tables to replace the fabricated
-- data previously generated by src/features/mentor-profile/services/mentorProfileFactory.ts
-- (invented education/certifications/projects/experience/reviews attributed to fake students).
-- See docs/BUG_REPORT.md BUG-41 for the full writeup.

-- =========================================================================
-- 1. mentor_experience — real work-history entries, mentor-managed
-- =========================================================================
CREATE TABLE IF NOT EXISTS public.mentor_experience (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    mentor_id       uuid NOT NULL REFERENCES public.mentor_profiles(id) ON DELETE CASCADE,
    company         text NOT NULL,
    company_logo_url text,
    role            text NOT NULL,
    starts_on       date NOT NULL,
    ends_on         date,
    is_current      boolean NOT NULL DEFAULT false,
    responsibilities text[] NOT NULL DEFAULT '{}',
    achievements    text[] NOT NULL DEFAULT '{}',
    sort_order      int NOT NULL DEFAULT 0,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    deleted_at      timestamptz,
    created_by      uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    updated_by      uuid REFERENCES public.profiles(id) ON DELETE SET NULL,

    CONSTRAINT mentor_experience_dates_check CHECK (ends_on IS NULL OR ends_on >= starts_on)
);

CREATE INDEX IF NOT EXISTS idx_mentor_experience_mentor_sort
    ON public.mentor_experience(mentor_id, sort_order);

CREATE TRIGGER set_updated_at_mentor_experience
    BEFORE UPDATE ON public.mentor_experience
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.mentor_experience ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public read mentor_experience" ON public.mentor_experience
    FOR SELECT USING (deleted_at IS NULL);
CREATE POLICY "Mentors manage own mentor_experience" ON public.mentor_experience
    FOR ALL USING (mentor_id = auth.uid()) WITH CHECK (mentor_id = auth.uid());
CREATE POLICY "Admins manage mentor_experience" ON public.mentor_experience
    FOR ALL USING (public.has_role('admin')) WITH CHECK (public.has_role('admin'));

-- =========================================================================
-- 2. mentor_projects — real portfolio projects, mentor-managed
-- =========================================================================
CREATE TABLE IF NOT EXISTS public.mentor_projects (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    mentor_id       uuid NOT NULL REFERENCES public.mentor_profiles(id) ON DELETE CASCADE,
    title           text NOT NULL,
    description     text,
    image_file_id   uuid REFERENCES public.files(id) ON DELETE SET NULL,
    tech_stack      text[] NOT NULL DEFAULT '{}',
    industry        text,
    difficulty      text CHECK (difficulty IN ('Beginner','Intermediate','Advanced')),
    github_url      text,
    live_url        text,
    sort_order      int NOT NULL DEFAULT 0,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    deleted_at      timestamptz,
    created_by      uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    updated_by      uuid REFERENCES public.profiles(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_mentor_projects_mentor_sort
    ON public.mentor_projects(mentor_id, sort_order);

CREATE TRIGGER set_updated_at_mentor_projects
    BEFORE UPDATE ON public.mentor_projects
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.mentor_projects ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public read mentor_projects" ON public.mentor_projects
    FOR SELECT USING (deleted_at IS NULL);
CREATE POLICY "Mentors manage own mentor_projects" ON public.mentor_projects
    FOR ALL USING (mentor_id = auth.uid()) WITH CHECK (mentor_id = auth.uid());
CREATE POLICY "Admins manage mentor_projects" ON public.mentor_projects
    FOR ALL USING (public.has_role('admin')) WITH CHECK (public.has_role('admin'));

