-- =========================================================================
-- 5. meetings: add a real attendee column so a student's own booking is
--    visible/cancellable by them (previously only host/admin had any access)
-- =========================================================================
ALTER TABLE public.meetings
    ADD COLUMN IF NOT EXISTS attendee_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_meetings_attendee ON public.meetings(attendee_id);

-- Booking creation itself stays admin/host-only at the RLS layer (mirrors the
-- enrollments/enroll-free precedent) - the book-mentor-session Edge Function
-- uses the service-role key to insert after re-validating availability server-side.
CREATE POLICY "Attendees view own booked meetings" ON public.meetings
    FOR SELECT USING (attendee_id = auth.uid());
CREATE POLICY "Attendees cancel own booking" ON public.meetings
    FOR UPDATE USING (attendee_id = auth.uid())
    WITH CHECK (attendee_id = auth.uid() AND status = 'cancelled');

-- =========================================================================
-- 6. get_mentor_available_slots — expands a mentor's recurring weekly
--    `availability` template into concrete free slots for a date range,
--    excluding any that overlap an existing non-cancelled `meetings` row.
--    SECURITY DEFINER so it can read `meetings` (host-only RLS) without
--    exposing meeting details - it only ever returns free start/end pairs.
-- =========================================================================
CREATE OR REPLACE FUNCTION public.get_mentor_available_slots(
    p_mentor_id uuid,
    p_start_date date,
    p_end_date date,
    p_slot_minutes int DEFAULT 45
)
RETURNS TABLE (slot_start timestamptz, slot_end timestamptz)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_day date;
BEGIN
    IF p_end_date < p_start_date THEN
        RETURN;
    END IF;
    IF p_end_date - p_start_date > 60 THEN
        RAISE EXCEPTION 'Date range too large (max 60 days)';
    END IF;

    FOR v_day IN SELECT generate_series(p_start_date, p_end_date, interval '1 day')::date LOOP
        RETURN QUERY
        SELECT gs.slot_start, gs.slot_start + make_interval(mins => p_slot_minutes)
        FROM public.availability a
        CROSS JOIN LATERAL generate_series(
            (v_day + a.start_time)::timestamptz,
            (v_day + a.end_time)::timestamptz - make_interval(mins => p_slot_minutes),
            make_interval(mins => p_slot_minutes)
        ) AS gs(slot_start)
        WHERE a.user_id = p_mentor_id
          AND a.is_active = true
          AND a.deleted_at IS NULL
          AND a.day_of_week = EXTRACT(DOW FROM v_day)::int
          AND gs.slot_start > now()
          AND NOT EXISTS (
              SELECT 1 FROM public.meetings m
              WHERE m.host_id = p_mentor_id
                AND m.status <> 'cancelled'
                AND m.starts_at < gs.slot_start + make_interval(mins => p_slot_minutes)
                AND m.ends_at > gs.slot_start
          );
    END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_mentor_available_slots(uuid, date, date, int) TO authenticated;

COMMENT ON FUNCTION public.get_mentor_available_slots IS
    'Returns free bookable slots for a mentor by expanding their weekly availability template and excluding conflicts with existing non-cancelled meetings. Used by the mentor-booking flow; never exposes meeting details.';
